int semaphore_signal(KernelState &kernel, const char *export_name, SceUID thread_id, SceUID semaid, int signal) {
#if defined(__SWITCH__) && defined(VITA3K_SWITCH_TRACELAB)
    // Only this signalling thread is host-only. Waiter outputs stay tracked.
    switch_validation::epoch::declare_outputs({"sceKernelSignalSema"}, {});
#endif

int condvar_signal(KernelState &kernel, const char *export_name, SceUID thread_id, SceUID condid, Condvar::SignalTarget signal_target, SyncWeight weight) {
#if defined(__SWITCH__) && defined(VITA3K_SWITCH_TRACELAB)
    // Only this signalling thread is host-only. Waiter outputs stay tracked.
    switch_validation::epoch::declare_outputs({"sceKernelSignalLwCond","sceKernelSignalLwCondAll","sceKernelSignalLwCondTo"}, {});
#endif

    TRACY_FUNC(sceGxmReserveFragmentDefaultUniformBuffer, context, uniformBuffer);
#if defined(__SWITCH__) && defined(VITA3K_SWITCH_TRACELAB)
    if (context && uniformBuffer && context->state.type == SCE_GXM_CONTEXT_TYPE_IMMEDIATE)
        switch_validation::epoch::declare_outputs({"sceGxmReserveFragmentDefaultUniformBuffer"},
            {{context, sizeof(*context)}, {uniformBuffer, sizeof(*uniformBuffer)}});
#endif

    TRACY_FUNC(sceGxmReserveVertexDefaultUniformBuffer, context, uniformBuffer);
#if defined(__SWITCH__) && defined(VITA3K_SWITCH_TRACELAB)
    if (context && uniformBuffer && context->state.type == SCE_GXM_CONTEXT_TYPE_IMMEDIATE)
        switch_validation::epoch::declare_outputs({"sceGxmReserveVertexDefaultUniformBuffer"},
            {{context, sizeof(*context)}, {uniformBuffer, sizeof(*uniformBuffer)}});
#endif

    if (cached != shaderPatcher->fragment_program_cache.end()) {
#if defined(__SWITCH__) && defined(VITA3K_SWITCH_TRACELAB)
        // Only the cache-hit branch has no Guest allocator/renderer work.
        const auto *observed_cached_program = cached->second.get(mem);
        if (observed_cached_program)
            switch_validation::epoch::declare_outputs({"sceGxmShaderPatcherCreateFragmentProgram"},
                {{&observed_cached_program->reference_count, sizeof(observed_cached_program->reference_count)},
                 {fragmentProgram, sizeof(*fragmentProgram)}});
#endif
        ++cached->second.get(mem)->reference_count;
        *fragmentProgram = cached->second;
        return 0;
    }

    if (cached != shaderPatcher->vertex_program_cache.end()) {
#if defined(__SWITCH__) && defined(VITA3K_SWITCH_TRACELAB)
        // Only the cache-hit branch has no Guest allocator/renderer work.
        const auto *observed_cached_program = cached->second.get(mem);
        if (observed_cached_program)
            switch_validation::epoch::declare_outputs({"sceGxmShaderPatcherCreateVertexProgram"},
                {{&observed_cached_program->reference_count, sizeof(observed_cached_program->reference_count)},
                 {vertexProgram, sizeof(*vertexProgram)}});
#endif
        ++cached->second.get(mem)->reference_count;
        *vertexProgram = cached->second;
        return 0;
    }
